CLASS_SHA='794a6d0df08fc2b777678b99013f61d0a9c93f5fbeacfaa3466c0feeaa9ada39'
CORE_SHA='21647e3c0537a8d56cd67cc67951206f7a84501acd74d0c8a827c13e192183c5'
